css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; }
.loader .rocket { position: absolute; left: 50%; bottom: 0; width: calc(var(--loader-size) * .24); height: calc(var(--loader-size) * .42); margin-left: calc(var(--loader-size) * -.12); background: linear-gradient(color-mix(in srgb, #fff 30%, var(--accent-2)), var(--accent)); border-radius: 50% 50% 30% 30%; animation: launch calc(var(--loader-speed) * 2) ease-in infinite; }
.loader .rocket::before { content: ''; position: absolute; bottom: calc(var(--loader-size) * -.12); left: 50%; width: 60%; height: calc(var(--loader-size) * .16); margin-left: -30%; background: linear-gradient(#fef08a, #f97316); border-radius: 0 0 50% 50%; clip-path: polygon(0 0, 100% 0, 50% 100%); animation: flame calc(var(--loader-speed) * .18) ease-in-out infinite alternate; }
.loader .rocket::after { content: ''; position: absolute; top: 26%; left: 50%; width: 40%; height: 40%; margin-left: -20%; border-radius: 50%; background: color-mix(in srgb, #fff 55%, var(--accent-2)); }
@keyframes launch { 0% { transform: translateY(85%); opacity: 0; } 16% { opacity: 1; } 84% { opacity: 1; } 100% { transform: translateY(-125%); opacity: 0; } }
@keyframes flame { 0% { transform: scaleY(.8); } 100% { transform: scaleY(1.2); } }
